/** CI-only real UI commands and private SQLite; document transport and scheduling are fake. */
public final class BackupDocumentFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private BackupActivity activity;
    private final class Fixture implements AutoCloseable {
        final SoundLabelFixture data;final Records.Factory oldRecords=Records.factory,records;final BackupDocuments.Factory oldFactory=BackupDocuments.factory;final BackupActivity.Picker oldPicker=BackupActivity.picker;
        final Map<String,?> preferences=new HashMap<>(Prefs.of(c).getAll());final Map<String,String> outside;final String production;final List<Activity> owned=new CopyOnWriteArrayList<>();final Application app=(Application)c.getApplicationContext();
        volatile CountDownLatch hold,entered;volatile boolean denied;volatile byte[] source,output;volatile int opens,retired;volatile CountDownLatch restoreHold,restoreEntered;BackupJob.Kind choice;
        final Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){assertTrue("Backup fixture may only open Main/Backup",a instanceof BackupActivity||a instanceof MainActivity);owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){if(a instanceof BackupActivity)activity=(BackupActivity)a;}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};
        Fixture()throws Exception {assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(TrackingService.running);assertFalse(AlarmService.active);assertFalse(Prefs.flag(c,"ringing"));assertFalse(Prefs.flag(c,"tracking"));outside=files(c.getFilesDir());try(Store store=new Store(c)){production=store.backup().toString();}data=new SoundLabelFixture(c);records=context->data.open();try(Store store=data.open()){Alarm a=new Alarm(92);a.label="Backup fixture nap";a.enabled=true;a.nap=new NapPlan(UUID.randomUUID().toString(),"backup-ui-private",System.currentTimeMillis()+60000,100000,5,20,true,NapPlan.Phase.PENDING,"");store.save(a);SoundLabels.save(store,data.snapshot(store),"speech");source=BackupIo.encode(store.backup().toString());}
            BackupDocuments.Transport transport=new BackupDocuments.Transport(){private void open()throws IOException{assertNotSame("Provider access must be off main",Looper.getMainLooper(),Looper.myLooper());opens++;CountDownLatch signal=entered;if(signal!=null)signal.countDown();CountDownLatch wait=hold;if(wait!=null)try{if(!wait.await(15,TimeUnit.SECONDS))throw new IOException("Fixture provider timed out");}catch(InterruptedException error){Thread.currentThread().interrupt();throw new IOException(error);}if(denied)throw new IOException("Fixture document access denied.");}public InputStream input(String uri)throws IOException{open();return new ByteArrayInputStream(source);}public OutputStream output(String uri)throws IOException{open();return new ByteArrayOutputStream(){@Override public void close(){output=toByteArray();}};}public void cancel(){CountDownLatch wait=hold;if(wait!=null)wait.countDown();}};
            BackupDocuments.Effects effects=new BackupDocuments.Effects(){public void idle(long admission){BackupRuntime.requireIdle(c,admission);}public void retired(List<Alarm> old,Store current){assertNotSame(Looper.getMainLooper(),Looper.myLooper());retired++;CountDownLatch signal=restoreEntered;if(signal!=null)signal.countDown();CountDownLatch wait=restoreHold;if(wait!=null)try{assertTrue(wait.await(15,TimeUnit.SECONDS));}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new IllegalStateException(interrupted);}}public void recover(Store store){SoundClips.recover(c,store);}};
            app.registerActivityLifecycleCallbacks(lifecycle);i.runOnMainSync(()->{Records.factory=records;BackupDocuments.factory=(context,pinned)->{assertSame(records,pinned);return new BackupDocuments(context,pinned,transport,effects);};BackupActivity.picker=(screen,kind)->choice=kind;});
        }
        BackupJob job(){return BackupJobs.get(c,records);}
        void result(boolean success)throws Exception{i.runOnMainSync(()->activity.onActivityResult(BackupActivity.DOCUMENT,success?Activity.RESULT_OK:Activity.RESULT_CANCELED,success?new Intent().setData(Uri.parse("content://backup-private/document")):null));i.waitForIdleSync();}
        void await(BackupJob.Phase phase)throws Exception{long end=SystemClock.elapsedRealtime()+10000;while(job().state().phase!=phase||job().state().occupied){if(SystemClock.elapsedRealtime()>=end)fail("Expected "+phase+", actual "+job().state().phase+": "+job().state().message);SystemClock.sleep(40);}i.waitForIdleSync();}
        @Override public void close()throws Exception{if(hold!=null)hold.countDown();if(restoreHold!=null)restoreHold.countDown();try{BackupJobs.drain(records,15000);i.waitForIdleSync();i.runOnMainSync(()->owned.forEach(a->{if(!a.isDestroyed())a.finish();}));long end=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<end)SystemClock.sleep(40);assertTrue(owned.stream().allMatch(Activity::isDestroyed));assertEquals(preferences,Prefs.of(c).getAll());try(Store store=new Store(c)){assertEquals(production,store.backup().toString());}assertFalse(TrackingService.running);assertFalse(AlarmService.active);BackupJobs.forget(records);}finally{app.unregisterActivityLifecycleCallbacks(lifecycle);i.runOnMainSync(()->{Records.factory=oldRecords;BackupDocuments.factory=oldFactory;BackupActivity.picker=oldPicker;});data.close();assertEquals("No file outside owned fixture changed",outside,files(c.getFilesDir()));}}
    }
    private Map<String,String> files(File root)throws Exception{Map<String,String> result=new TreeMap<>();if(!root.exists())return result;try(java.util.stream.Stream<Path> paths=Files.walk(root.toPath())){for(Path path:(Iterable<Path>)paths::iterator)if(Files.isRegularFile(path)){MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream input=Files.newInputStream(path)){byte[] block=new byte[8192];for(int n;(n=input.read(block))!=-1;)digest.update(block,0,n);}result.put(root.toPath().relativize(path).toString(),Base64.getEncoder().encodeToString(digest.digest()));}}return result;}
    private void launch()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(BackupActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,BackupActivity.class).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(BackupActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}text("Backup");}
    private void recreate()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(BackupActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(BackupActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}text("Backup");}
    private void text(String text){assertTrue(text,device.wait(Until.hasObject(By.text(text)),5000));}
    private UiObject2 button(String text)throws Exception{UiObject2 view=device.wait(Until.findObject(By.text(text)),2000);if(view==null){UiScrollable scroll=new UiScrollable(new UiSelector().scrollable(true));if(scroll.exists())scroll.scrollIntoView(new UiSelector().text(text));view=device.wait(Until.findObject(By.text(text)),3000);}assertNotNull(text,view);return view;}
    private void click(String text)throws Exception{button(text).click();device.waitForIdle();}
    private void confirmation(String description)throws Exception{UiObject2 control=device.wait(Until.findObject(By.desc(description)),5000);assertNotNull(description,control);control.click();assertTrue(device.wait(Until.gone(By.desc(description)),5000));}
    private void finish()throws Exception{BackupActivity closing=activity;i.runOnMainSync(closing::finish);long end=SystemClock.elapsedRealtime()+5000;while(!closing.isDestroyed()&&SystemClock.elapsedRealtime()<end)SystemClock.sleep(40);assertTrue(closing.isDestroyed());}
    private void capture(String suffix)throws Exception{CountDownLatch committed=new CountDownLatch(1);boolean[] registered={false};long end=SystemClock.elapsedRealtime()+5000;while(!registered[0]&&SystemClock.elapsedRealtime()<end){i.runOnMainSync(()->{View decor=activity.getWindow().getDecorView();if(activity.hasWindowFocus()&&decor.isAttachedToWindow()&&decor.isHardwareAccelerated()){decor.getViewTreeObserver().registerFrameCommitCallback(committed::countDown);decor.invalidate();registered[0]=true;}});if(!registered[0])SystemClock.sleep(40);}assertTrue("Focused Backup frame",registered[0]);assertTrue(committed.await(5,TimeUnit.SECONDS));File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"backup-document-"+suffix+".png")));}
    @Test public void realMainRouteProviderWaitCancelRecreateAndCsvStayResponsive()throws Exception{try(Fixture f=new Fixture()){
        Instrumentation.ActivityMonitor mainMonitor=i.addMonitor(MainActivity.class.getName(),null,false);MainActivity main;try{c.startActivity(new Intent(c,MainActivity.class).putExtra("destination",3).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));main=(MainActivity)mainMonitor.waitForActivityWithTimeout(5000);assertNotNull(main);}finally{i.removeMonitor(mainMonitor);}click("Data & privacy");Instrumentation.ActivityMonitor backup=i.addMonitor(BackupActivity.class.getName(),null,false);try{click("Export backup");activity=(BackupActivity)backup.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(backup);}assertEquals(BackupJob.Kind.JSON,f.choice);capture("chooser");f.result(false);f.await(BackupJob.Phase.CANCELLED);capture("selection-cancelled");
        f.entered=new CountDownLatch(1);f.hold=new CountDownLatch(1);click("Export backup");f.result(true);assertTrue(f.entered.await(5,TimeUnit.SECONDS));text("Saving document…");CountDownLatch heartbeat=new CountDownLatch(1);new Handler(Looper.getMainLooper()).post(heartbeat::countDown);assertTrue("Delayed provider must not block main Looper",heartbeat.await(1,TimeUnit.SECONDS));capture("writing");recreate();text("Saving document…");capture("writing-recreated");click("Cancel operation");f.await(BackupJob.Phase.CANCELLED);assertEquals(1,f.opens);assertTrue(f.data.file.exists());capture("cancelled");f.hold=null;f.entered=null;
        click("Export records as CSV");assertEquals(BackupJob.Kind.CSV,f.choice);f.result(true);f.await(BackupJob.Phase.DONE);text("CSV saved with sleep records, notes and tags.");try(Store store=f.data.open()){assertEquals(Records.csv(store),new String(f.output,java.nio.charset.StandardCharsets.UTF_8));}capture("csv-done");
    }}
    @Test public void explicitReviewedReplacementPersistsAcrossRotationAndReopen()throws Exception{try(Fixture f=new Fixture()){
        launch();click("Import backup");f.result(true);f.await(BackupJob.Phase.REVIEW);text("Review replacement");assertEquals(0,f.retired);capture("review");click("Review replacement");assertNotNull(device.wait(Until.findObject(By.desc("Confirm backup replacement")),5000));capture("confirmation");confirmation("Cancel backup replacement");assertEquals(0,f.retired);recreate();text("Review replacement");capture("review-recreated");finish();launch();text("Review replacement");capture("review-reopened");
        f.restoreEntered=new CountDownLatch(1);f.restoreHold=new CountDownLatch(1);click("Review replacement");confirmation("Confirm backup replacement");assertTrue(f.restoreEntered.await(5,TimeUnit.SECONDS));text("Replacing local data…");capture("restoring");recreate();text("Replacing local data…");capture("restoring-recreated");assertEquals(1,f.retired);f.restoreHold.countDown();f.await(BackupJob.Phase.DONE);text("Data restored. Review and enable your alarms.");try(Store store=f.data.open()){assertFalse(store.alarm(92).enabled);assertEquals(NapPlan.Phase.CANCELLED,store.alarm(92).nap.phase);JSONObject event=f.data.event(store);assertEquals("speech",event.getString("user_category"));assertTrue(event.isNull("clip"));}assertFalse(f.data.file.exists());capture("restored");finish();launch();text("Data restored. Review and enable your alarms.");capture("result-reopened");assertEquals(1,f.retired);
    }}
    @Test public void deniedOversizedMalformedAndStaleImportsNeverReplaceData()throws Exception{try(Fixture f=new Fixture()){
        launch();String before;try(Store store=f.data.open()){before=BackupFingerprint.read(store);}byte[] valid=f.source;f.denied=true;click("Import backup");f.result(true);f.await(BackupJob.Phase.ERROR);capture("denied");f.denied=false;f.source=new byte[BackupIo.LIMIT+1];click("Import backup");f.result(true);f.await(BackupJob.Phase.ERROR);assertTrue(f.job().state().message.contains("8 MiB"));capture("oversized");f.source="{broken".getBytes(java.nio.charset.StandardCharsets.UTF_8);click("Import backup");f.result(true);f.await(BackupJob.Phase.ERROR);capture("malformed");try(Store store=f.data.open()){assertEquals(before,BackupFingerprint.read(store));}
        f.source=valid;click("Import backup");f.result(true);f.await(BackupJob.Phase.REVIEW);try(Store store=f.data.open()){SoundLabels.save(store,f.data.snapshot(store),"cough");}click("Review replacement");confirmation("Confirm backup replacement");f.await(BackupJob.Phase.ERROR);assertTrue(f.job().state().message.contains("Local data changed"));capture("stale");assertEquals(0,f.retired);assertTrue(f.data.file.exists());
        click("Import backup");f.result(true);f.await(BackupJob.Phase.REVIEW);BackupRuntime.admitted();click("Review replacement");confirmation("Confirm backup replacement");f.await(BackupJob.Phase.ERROR);assertTrue(f.job().state().message.contains("Tracking or an alarm started"));capture("runtime-admission");try(Store store=f.data.open()){assertEquals("cough",f.data.event(store).getString("user_category"));}assertEquals(0,f.retired);
    }}
}
